import{z as p,x as A,o as e,c as d,q as s,j as n,D as r,d as o,s as E,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"稀疏表","description":"","frontmatter":{"title":"稀疏表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-table.md","filePath":"cs/sparse-table.md","lastUpdated":1791413859000}'),B={name:"cs/sparse-table.md"};function m(D,a,T,u,f,h){const t=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=s('<h1 id="稀疏表" tabindex="-1">稀疏表 <a class="header-anchor" href="#稀疏表" aria-label="Permalink to &quot;稀疏表&quot;">​</a></h1><div class="epigraph"><p>把每个起点的 $2^k$ 长窗口预先算好，任意区间用两块对齐的 2 的幂盖住；幂等运算下重叠不要紧。</p><footer>—— 据 Bender and Farach-Colton, The LCA Problem Revisited, LATIN 2000；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/prefix-sum-difference">上一课</a>把可逆的区间和收成两次查表。最大值、最小值、最大公因数没有群逆，\\(S[r]-S[l-1]\\) 无意义。本课不重做差分。缺口是静态、<strong>幂等</strong>（或可重叠）的区间查询：稀疏表（sparse table）用 \\(O(n\\log n)\\) 空间换 \\(O(1)\\) 查询。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>区间 \\([l,r]\\) 长度 \\(len=r-l+1\\)，令 \\(k=\\lfloor\\log_2 len\\rfloor\\)。两段 \\([l,l+2^k-1]\\) 与 \\([r-2^k+1,r]\\) 并起来覆盖 \\([l,r]\\)，中间重叠。若运算 \\(\\oplus\\) 满足 \\(x\\oplus x=x\\)（幂等）且结合，则</p> \\[A[l]\\oplus\\cdots\\oplus A[r] = \\mathrm{ST}[k][l]\\oplus \\mathrm{ST}[k][r-2^k+1]. \\]<p>缺口不是新的数组布局，而是<strong>按长度的 2 的幂做倍增预处理</strong>。RMQ（区间最值）是标准实例；LCA 化 RMQ 时同一张表出现，本课只钉序列上的表。</p><p><span class="marginnote">数字实例：区间 \\([l,r]\\) 长 6，\\(k=\\lfloor\\log_2 6\\rfloor=2\\)，两块各长 \\(2^2=4\\)：\\([l,l+3]\\) 与 \\([r-3,r]=[l+2,l+5]\\)，中间 \\([l+2,l+3]\\) 被盖了两次。求 max 没关系；求和就把这两个元素算了双份——这就是幂等性这道门槛的由来。</span></p><p><span class="marginnote">\\(\\mathrm{ST}[k][i]\\) 表示从 \\(i\\) 起长 \\(2^k\\) 的窗口聚合。建表：\\(\\mathrm{ST}[k][i]=\\mathrm{ST}[k-1][i]\\oplus\\mathrm{ST}[k-1][i+2^{k-1}]\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建表 \\(\\Theta(n\\log n)\\)：先 \\(k=0\\) 抄 \\(A\\)，再按 \\(k\\) 升。查询读 \\(\\lfloor\\log_2(r-l+1)\\rfloor\\)，两次表项 \\(\\oplus\\)。\\(\\log\\) 可预处理成每个长度一张表，避免查询时算浮点。数组不可改：改一个点要重建，或退回后课可更新结构。</p>',11)),(e(),n(i,null,{default:r(()=>[E(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%9D%99%E6%80%81%E5%BA%8F%E5%88%97%22%5D%20--%3E%20ST%5B%22ST%5Bk%5D%5Bi%5D%20%3D%20%E9%95%BF%202%5Ek%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20Q%5B%22%E5%8C%BA%E9%97%B4%20%5Bl%2C%20r%5D%5D%20--%3E%20TWO%5B%E4%B8%A4%E5%9D%97%202%5Ek%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20ST%20--%3E%20TWO%0A%20%20TWO%20--%3E%20IDEM%5B%22%E5%B9%82%E7%AD%89%3A%20%E9%87%8D%E5%8F%A0%E5%8F%AF%E9%87%8D%E5%A4%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"与前缀和对照：前缀和靠逆元消去中间，稀疏表靠重叠可重复。两者都静态。",-1)),a[4]||(a[4]=l("p",null,[l("span",{class:"marginnote"},"直觉类比：稀疏表像预先折好一排不同长度（1、2、4、8……）的尺子。查询时挑两把最长的、能盖住区间的尺子，允许中间重叠——只要「重叠不改变答案」（幂等），这种偷懒就成立；求和这种对顺序敏感的运算用不了这招。")],-1)),a[5]||(a[5]=l("h2",{id:"机制",tabindex:"-1"},[o("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=l("p",null,"空间 \\(\\Theta(n\\log n)\\) 个聚合结果，比前缀和厚一截，换来无逆运算。查询两次随机读，常数小于线段树的 \\(O(\\log n)\\) 次访存——静态 RMQ 常因此选稀疏表。不幂等的求和不能用两块覆盖（中间被加两次）；求和请回上一课。",-1)),a[7]||(a[7]=l("p",null,"\\(\\lfloor\\log_2\\rfloor\\) 表本身是 \\(O(n)\\) 预处理。建表顺序必须从小窗口到大窗口，否则引用尚未写出的半段。",-1)),(e(),n(i,null,{default:r(()=>[E(t,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUM%5B%22%E5%8C%BA%E9%97%B4%E6%B1%82%E5%92%8C%22%5D%20--%3E%20OV%5B%22%E4%B8%A4%E5%9D%97%E8%A6%86%E7%9B%96%E6%9C%89%E9%87%8D%E5%8F%A0%22%5D%0A%20%20OV%20--%3E%20TWICE%5B%22%E9%87%8D%E5%8F%A0%E5%85%83%E7%B4%A0%E8%A2%AB%E5%8A%A0%E4%B8%A4%E6%AC%A1%22%5D%0A%20%20TWICE%20--%3E%20WRONG%5B%22%E7%BB%93%E6%9E%9C%E9%94%99%E8%AF%AF%22%5D%0A%20%20MIN%5B%22%E5%8C%BA%E9%97%B4%E6%9C%80%E5%B0%8F%E5%80%BC%22%5D%20--%3E%20OV2%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%E9%87%8D%E5%8F%A0%22%5D%0A%20%20OV2%20--%3E%20IDEM%5B%22max%2Fmin%20%E6%BB%A1%E8%B6%B3%20x%E2%8A%95x%20%3D%20x%22%5D%0A%20%20IDEM%20--%3E%20OK%5B%22%E7%BB%93%E6%9E%9C%E4%BB%8D%E6%AD%A3%E7%A1%AE%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p>这张图回答的是：为什么「幂等」是两块覆盖的硬性前提——同样的重叠，对求和是重复计数，对最值是无害重复，运算性质决定结构能不能这么搭。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Fischer–Heun 的 \\(O(n)\\) 空间 RMQ 写完，也不把树剖成欧拉序。单点修改、区间加都不属于稀疏表合同。需要更新时，下一课树状数组走可加群的另一条路。</p><p><span class="marginnote">常见误区：初学者容易把稀疏表当成「能改的线段树替代品」。改一个点要沿倍增关系重算约 \\(\\log n\\) 个表项，批量改等于重建——它的合同是「建好之后只读」，定价换的是 \\(O(1)\\) 查询。</span></p><p>后课默认：静态幂等区间查询可以 \\(O(1)\\)；要改数组，换树状结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏表：\\(O(n\\log n)\\) 建，\\(O(1)\\) 幂等区间查询。</li><li>覆盖用两段等长 2 的幂；求和请用前缀和。</li><li>可更新的加法结构从树状数组开始。</li><li>出处：Bender and Farach-Colton, LATIN 2000；Cormen et al.。</li></ul>',7))])}const g=p(B,[["render",m]]);export{C as __pageData,g as default};
